def is_preempted(job, current_time, processor_state):
    if job.is_enabled(current_time) and not job.is_suspended(current_time):
        if not processor_state.is_executing(job, current_time):
            return True
    return False

def transform_schedule_to_busy_interval(schedule_S, tau_l_j):
    r_l_j = tau_l_j.release_time
    d_l_j = tau_l_j.deadline
    schedule_S_prime = deepcopy(schedule_S)

    for t in range(r_l_j, d_l_j):
        if schedule_S.is_idle_at(t):
            # If tau_l_j is suspending at t and processor is idle
            if schedule_S.job_is_suspending(tau_l_j, t):
                # Convert tau_l_j's suspension to computation in S_prime
                schedule_S_prime.convert_suspension_to_computation(tau_l_j, t)

    # After transformation, the interval [r_l_j, d_l_j) in S_prime should be busy
    return schedule_S_prime

def calculate_lhs_eq1(tasks_on_processor):
    if not tasks_on_processor: return 0
    # Sort tasks by period for RM priority
    sorted_tasks = sorted(tasks_on_processor, key=lambda t: t.p)
    max_lhs = 0
    for k_idx, tau_k in enumerate(sorted_tasks):
        current_sum_u = sum(t.u for t in sorted_tasks[:k_idx+1])
        lhs_val = current_sum_u + tau_k.s / tau_k.p
        if lhs_val > max_lhs: max_lhs = lhs_val
    return max_lhs

def calculate_delta(tau_i, M_k_tasks):
    lhs_before = calculate_lhs_eq1(M_k_tasks)
    lhs_after = calculate_lhs_eq1(M_k_tasks + [tau_i])
    return lhs_after - lhs_before

def get_available_utilization(M_j_tasks):
    return 1.0 - sum(t.u for t in M_j_tasks)
